import { test, expect } from '@playwright/test';

test.describe('Modal Fullscreen on Small Viewports', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-page');
  });

  test('should display modal as full screen on small viewports', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    const modalContainer = page.locator('[data-testid="modal-container"]');
    await expect(modalContainer).toBeVisible();

    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    const modalHeader = page.locator('[data-testid="modal-header"]');
    await expect(modalHeader).toBeVisible();

    const modalBody = page.locator('[data-testid="modal-body"]');
    await expect(modalBody).toBeVisible();

    const modalFooter = page.locator('[data-testid="modal-footer"]');
    await expect(modalFooter).toBeVisible();

    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    const modalOverlay = page.locator('[data-testid="modal-overlay"]');
    await expect(modalOverlay).toBeVisible();

    const modalContainerBoundingBox = await modalContainer.boundingBox();
    const viewportBoundingBox = await page.locator('body').boundingBox();

    expect(modalContainerBoundingBox.width).toBeGreaterThan(viewportBoundingBox.width * 0.9);
    expect(modalContainerBoundingBox.height).toBeGreaterThan(viewportBoundingBox.height * 0.9);
  });

  test('should not display modal as full screen on large viewports', async ({ page }) => {
    await page.setViewportSize({ width: 1200, height: 800 });

    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    const modalContainer = page.locator('[data-testid="modal-container"]');
    await expect(modalContainer).toBeVisible();

    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    const modalHeader = page.locator('[data-testid="modal-header"]');
    await expect(modalHeader).toBeVisible();

    const modalBody = page.locator('[data-testid="modal-body"]');
    await expect(modalBody).toBeVisible();

    const modalFooter = page.locator('[data-testid="modal-footer"]');
    await expect(modalFooter).toBeVisible();

    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    const modalOverlay = page.locator('[data-testid="modal-overlay"]');
    await expect(modalOverlay).toBeVisible();

    const modalContainerBoundingBox = await modalContainer.boundingBox();
    const viewportBoundingBox = await page.locator('body').boundingBox();

    expect(modalContainerBoundingBox.width).toBeLessThan(viewportBoundingBox.width * 0.9);
    expect(modalContainerBoundingBox.height).toBeLessThan(viewportBoundingBox.height * 0.9);
  });
});
